import os, base64
files = {"bot/test_setup.py": "", "bot/main.py": "", "bot/config.py": "", "bot/setup_api_key.py": "", "bot/test_api.py": "", "bot/risk/risk_manager.py": "", "bot/risk/__init__.py": "", "bot/polymarket/api_client.py": "", "bot/polymarket/market_scanner.py": "", "bot/polymarket/simulated_contracts.py": "", "bot/polymarket/__init__.py": "", "bot/utils/database.py": "", "bot/utils/__init__.py": "", "bot/utils/dashboard.py": "", "bot/strategy/signal_engine.py": "", "bot/strategy/__init__.py": "", "bot/feeds/binance_ws.py": "", "bot/feeds/__init__.py": "", "bot/execution/paper_engine.py": "", "bot/execution/__init__.py": "", "bot/execution/live_engine.py": ""}

for path, b64 in files.items():
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "wb") as f:
        f.write(base64.b64decode(b64))
    print("Restored:", path)
print("DONE")
